/**
 * Sprint 28R — Decision Support Shadow Capture Storage Adapter Fake Implementation: fixture corpus.
 *
 * A small, hand-authored corpus exercising `createDecisionSupportShadowStorageFakeAdapter()`'s
 * `writeDraft()`/`deleteByCaptureId()`/`deleteByWorkspace()`/`purgeExpired()`/`listByPolicyVersion()`
 * end to end, plus config-rejection and no-real-storage documentation scenarios. Each case documents,
 * via `notes`, exactly which fake-adapter behavior it proves — the test file
 * (`tests/playbook-engine-conversation-decision-support-shadow-storage-fake-adapter.test.mjs`) drives
 * every case against either a real, corpus-derived draft (built via the real Sprint 24R -> Sprint 25R
 * -> Sprint 27R pipeline) or a synthetic draft the case itself describes how to construct.
 *
 * None of this ever writes a database, calls Supabase, or persists anything outside a single test's
 * own in-process fake adapter instance.
 */

export type DecisionSupportShadowStorageFakeAdapterCaseKind =
  | "config_rejection"
  | "valid_write"
  | "forbidden_field_rejection"
  | "policy_flag_rejection"
  | "delete_behavior"
  | "purge_behavior"
  | "list_behavior"
  | "stats_behavior"
  | "clear_behavior"
  | "documentation";

export type DecisionSupportShadowStorageFakeAdapterCase = {
  id: string;
  kind: DecisionSupportShadowStorageFakeAdapterCaseKind;
  scenario: string;
  /** Which harness fixture case (`cap-01`..`cap-07`) to build a real draft from, when relevant. */
  sourceCaptureHarnessCaseId?: string;
  /** A forbidden field name to inject into `draft.fields`, for forbidden_field_rejection cases. */
  forbiddenField?: string;
  forbiddenFieldValue?: unknown;
  /** A top-level policy flag name (`storageEnabled` | `realPersistenceAllowed`) to force true. */
  policyFlag?: "storageEnabled" | "realPersistenceAllowed";
  /** Adapter config overrides applied for this case only. */
  configOverrides?: Record<string, unknown>;
  expectedWriteStatus?: string;
  expectedDeleteStatus?: string;
  expectedPurgeStatus?: string;
  expectedListStatus?: string;
  expectedAccepted?: boolean;
  expectedRejected?: boolean;
  expectedRealPersistenceAttempted: false;
  expectedDbWriteAttempted: false;
  expectedSupabaseWriteAttempted: false;
  expectedForbiddenStored: false;
  notes: string;
};

